// ============================================
// SITE CONFIGURATION
// Edit these values for your WordPress site
// ============================================
const CONFIG = {
  site_url: 'https://yoursite.com',  // WordPress site URL (no trailing slash)
  stale_days: 180,                    // Flag posts not updated in this many days
  min_word_count: 300,                // Flag posts with fewer words than this
  max_posts: 100                      // Number of recent posts to analyze
};

return [{ json: CONFIG }];

const items = $input.all();
const now = new Date();
const STALE_DAYS = 180;
const MIN_WORDS = 300;

const results = {
  total_posts: items.length,
  stale_posts: [],
  thin_content: [],
  missing_images: []
};

for (const item of items) {
  const post = item.json;
  const title = post.title?.rendered || post.title || 'Untitled';
  const modified = new Date(post.modified || post.date);
  const daysSinceUpdate = Math.floor((now - modified) / 86400000);

  // Strip HTML and count words
  const content = (post.content?.rendered || '').replace(/<[^>]*>/g, ' ');
  const wordCount = content.split(/\s+/).filter(w => w.length > 0).length;

  // Check for stale content
  if (daysSinceUpdate > STALE_DAYS) {
    results.stale_posts.push({
      title,
      link: post.link,
      days_since_update: daysSinceUpdate,
      last_modified: modified.toISOString().split('T')[0]
    });
  }

  // Check for thin content
  if (wordCount < MIN_WORDS && wordCount > 0) {
    results.thin_content.push({
      title,
      link: post.link,
      word_count: wordCount
    });
  }

  // Check for posts without images in opening content
  const firstChunk = (post.content?.rendered || '').substring(0, 1000);
  const hasFeatured = Number(post.featured_media || 0) > 0;
  const hasInline = (post.content?.rendered || '').includes('<img');
  if (!hasFeatured && !hasInline) {
    results.missing_images.push({ title, link: post.link });
  }
}

// Sort stale by most outdated first
results.stale_posts.sort((a, b) => b.days_since_update - a.days_since_update);

return [{ json: results }];

const data = $input.first().json;

let report = '\ud83d\udcca Content Health Report\n';
report += '\u2501'.repeat(24) + '\n';
report += `Posts scanned: ${data.total_posts}\n\n`;

if (data.stale_posts.length > 0) {
  report += `\ud83d\udd34 Stale Content (${data.stale_posts.length} posts not updated in 180+ days):\n`;
  for (const post of data.stale_posts.slice(0, 5)) {
    report += `  \u2022 ${post.title} \u2014 ${post.days_since_update} days\n`;
  }
  if (data.stale_posts.length > 5) {
    report += `  ... and ${data.stale_posts.length - 5} more\n`;
  }
  report += '\n';
}

if (data.thin_content.length > 0) {
  report += `\ud83d\udfe1 Thin Content (${data.thin_content.length} posts under 300 words):\n`;
  for (const post of data.thin_content.slice(0, 5)) {
    report += `  \u2022 ${post.title} \u2014 ${post.word_count} words\n`;
  }
  if (data.thin_content.length > 5) {
    report += `  ... and ${data.thin_content.length - 5} more\n`;
  }
  report += '\n';
}

if (data.missing_images.length > 0) {
  report += `\ud83d\udfe0 Missing Lead Image (${data.missing_images.length} posts):\n`;
  for (const post of data.missing_images.slice(0, 5)) {
    report += `  \u2022 ${post.title}\n`;
  }
  if (data.missing_images.length > 5) {
    report += `  ... and ${data.missing_images.length - 5} more\n`;
  }
  report += '\n';
}

const score = Math.round(((data.total_posts - data.stale_posts.length - data.thin_content.length) / Math.max(data.total_posts, 1)) * 100);
report += `\n\u2b50 Health Score: ${score}%`;

return [{ json: { report, health_score: score, ...data } }];

const data = $input.first().json;
const timestamp = new Date().toISOString().split('T')[0];

const summary = {
  date: timestamp,
  total_posts: data.total_posts,
  stale_count: data.stale_posts?.length || 0,
  thin_count: data.thin_content?.length || 0,
  missing_images_count: data.missing_images?.length || 0,
  health_score: data.health_score
};

return [{ json: { message: `Report complete. Health score: ${summary.health_score}%`, summary } }];
